export const matriz = {
  empresa: "Tienda en línea",
  filas: [
    { escenario: "Comprar servidores para el pico de ventas y dejarlos ociosos el resto del año", beneficio: "ELASTICIDAD" },
    { escenario: "Esperar semanas a que lleguen servidores para probar una idea", beneficio: "AGILIDAD" },
    { escenario: "Acercar la aplicación a clientes de otro continente para reducir la latencia", beneficio: "ALCANCE_GLOBAL" },
    { escenario: "Invertir en servidores antes de conocer cuántos clientes habrá", beneficio: "GASTO_VARIABLE" },
    { escenario: "Dedicar al equipo a montar y alimentar servidores propios", beneficio: "SIN_CENTROS_DE_DATOS" },
  ],
};

spec.code:
const fila = matriz.filas.find((f) => f.escenario === "Invertir en servidores antes de conocer cuántos clientes habrá");
assert.ok(fila, "debe existir la fila de inversión por adelantado");
assert.strictEqual(fila.beneficio, "GASTO_VARIABLE");

const validos = ["GASTO_VARIABLE", "ECONOMIA_DE_ESCALA", "ELASTICIDAD", "AGILIDAD", "SIN_CENTROS_DE_DATOS", "ALCANCE_GLOBAL"];
for (const fila of matriz.filas) {
  assert.ok(validos.includes(fila.beneficio), fila.escenario + " tiene un beneficio no válido");
}

const esperado = {
  "Comprar servidores para el pico de ventas y dejarlos ociosos el resto del año": "ELASTICIDAD",
  "Esperar semanas a que lleguen servidores para probar una idea": "AGILIDAD",
  "Acercar la aplicación a clientes de otro continente para reducir la latencia": "ALCANCE_GLOBAL",
  "Dedicar al equipo a montar y alimentar servidores propios": "SIN_CENTROS_DE_DATOS",
};
for (const [escenario, beneficio] of Object.entries(esperado)) {
  const fila = matriz.filas.find((f) => f.escenario === escenario);
  assert.ok(fila, escenario + " debe seguir existiendo");
  assert.strictEqual(fila.beneficio, beneficio);
}

