// Capacidad sin usar de una carga de trabajo según el modelo de infraestructura. Corrige su defecto principal.
export type Modelo = "centro-de-datos-propio" | "nube";

export function capacidadOciosa(demanda: number[], modelo: Modelo): number {
  const pico = Math.max(...demanda);
  const aprovisionada = demanda.map(() => pico);
  return aprovisionada.reduce((suma, capacidad, hora) => suma + (capacidad - demanda[hora]), 0);
}

solution.code:
export type Modelo = "centro-de-datos-propio" | "nube";

export function capacidadOciosa(demanda: number[], modelo: Modelo): number {
  const pico = Math.max(...demanda);
  const aprovisionada = modelo === "nube" ? [...demanda] : demanda.map(() => pico);
  return aprovisionada.reduce((suma, capacidad, hora) => suma + (capacidad - demanda[hora]), 0);
}
